  imp <- ifelse(same, as.numeric(adae$TRTSDT[ym]), as.numeric(first))
  imp <- ifelse(!is.na(adae$AENDT[ym]) & imp > as.numeric(adae$AENDT[ym]), as.numeric(first), imp)
